def _app_keys_dir() -> Path:
    return _paths.manager_home() / "secrets" / "app_keys"


def store_app_key(key_id: str, data: dict) -> Path:
    """Encrypt and write an application API key."""
    d = _app_keys_dir()
    d.mkdir(parents=True, exist_ok=True)
    path = d / f"{key_id}.enc"
    path.write_bytes(encrypt(data))
    path.chmod(0o600)
    return path


def load_app_key(key_id: str) -> dict:
    """Read and decrypt an application API key."""
    path = _app_keys_dir() / f"{key_id}.enc"
    if not path.exists():
        raise VaultError(f"No app key found for {key_id!r}")
    return decrypt(path.read_bytes())


def delete_app_key(key_id: str) -> bool:
    """Delete an app key file. Returns True if deleted, False if not found."""
    path = _app_keys_dir() / f"{key_id}.enc"
    if not path.exists():
        return False
    path.unlink()
    return True


def list_app_keys() -> list[dict]:
    """List all stored app keys (metadata only — no secret values)."""
    d = _app_keys_dir()
    if not d.exists():
        return []
    results = []
    for p in sorted(d.glob("*.enc")):
        key_id = p.stem
        try:
            data = decrypt(p.read_bytes())
            results.append({
                "key_id": key_id,
                "provider": data.get("provider", ""),
                "purpose": data.get("purpose", ""),
                "created_at": data.get("created_at", ""),
            })
        except VaultError:
            results.append({"key_id": key_id, "provider": "?", "purpose": "decrypt failed"})
    return results
